import "./AuthForm.css";
import * as userService from "../../../Services/AuthService";
import React, { useState } from "react";
import { useUser } from "../../../Contexts/User/UserContext";
import Card from "../../../Components/CardContainer/Card";
import { Navigate } from "react-router-dom";

const AuthForm = () => {
  const [step, setStep] = useState(0); // 0 for login, 1 for registration client, 2 for registration trainer, 3 for OTP verification,
  const [email, setEmail] = useState("");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [otpCode, setOtpCode] = useState("");
  const { setUser } = useUser();
  const [active, setActive] = useState<"client" | "trainer">("client");

  const handleLogin = async () => {
    try {
      const response = await userService.loginUser({ email, password });
      if (response) {
        setStep(3);
      }
    } catch (error) {
      console.error("Login failed");
    }
  };

  const handleVerifyOtp = async () => {
    try {
      const response = await userService.verifyOtp({ email, otpCode });

      if (response.user) {
        setUser(response.user);
        console.log("OTP verification successful", response.user);
      } else {
        console.error("OTP verification failed: User not found in response");
      }
    } catch (error) {
      console.error("OTP verification failed");
    }
  };

  const handleSignUpButtonClick = () => {
    setStep(1);
  };

  return (
    <Card>
      <div className="auth-form">
        {step === 0 && (
          <div className="auth-options">
            <h2>Login</h2>
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button onClick={handleLogin} className="log-in-button">
              Log In
            </button>
            <a
              className="link-button-sign-up"
              onClick={handleSignUpButtonClick}
            >
              Don`t have an account yet? Sign up
            </a>
          </div>
        )}
        {step === 1 && (
          <div className="auth-options">
            <h2>Sign Up</h2>
            <div className="sign-up-options">
              <div
                className={`option ${
                  active === "client" ? "active-option" : ""
                }`}
                onClick={() => setActive("client")}
              >
                Client
              </div>
              <div
                className={`option ${
                  active === "trainer" ? "active-option" : ""
                }`}
                onClick={() => setActive("trainer")}
              >
                Trainer
              </div>
            </div>

            <div className="sign-up">
              <input
                className="auth-input"
                type="text"
                placeholder="First Name"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
                required
              />
              <input
                className="auth-input"
                type="text"
                placeholder="Last Name"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
                required
              />
              <input
                className="auth-input"
                type="email"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
              <input
                className="auth-input"
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
              <input
                className="auth-input"
                type="tel"
                pattern="^\+380\d{9}$"
                placeholder="+380XXXXXXXXX"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                required
              />
            </div>

            {active === "trainer" && (
              <div className="sign-up">
                <input
                  type="text"
                  placeholder=""
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            )}
          </div>
        )}

        {step === 3 && (
          <div className="auth-options">
            <h2>Verify OTP</h2>
            <input
              type="text"
              placeholder="Enter OTP code"
              value={otpCode}
              onChange={(e) => setOtpCode(e.target.value)}
            />
            <button onClick={handleVerifyOtp}>Verify OTP</button>
          </div>
        )}
      </div>
    </Card>
  );
};

export default AuthForm;
